package com.jadhavr.erp.academic.entity;
import com.jadhavr.erp.academic.enums.AcademicStatus; import com.jadhavr.erp.common.entity.BaseAuditEntity; import com.jadhavr.erp.student.entity.StudentProfile; import jakarta.persistence.*; import java.time.LocalDateTime;
@Entity @Table(name="student_section_enrollments",uniqueConstraints=@UniqueConstraint(columnNames={"student_id","academic_year"})) public class StudentSectionEnrollment extends BaseAuditEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="student_id",nullable=false) private StudentProfile student; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="section_id",nullable=false) private Section section; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="academic_class_id",nullable=false) private AcademicClass academicClass; @Column(name="academic_year",nullable=false) private String academicYear; @Column(name="roll_number",nullable=false) private String rollNumber; @Enumerated(EnumType.STRING) private AcademicStatus status=AcademicStatus.ACTIVE; private LocalDateTime enrolledAt=LocalDateTime.now();
public Long getId(){return id;} public StudentProfile getStudent(){return student;} public void setStudent(StudentProfile v){student=v;} public Section getSection(){return section;} public void setSection(Section v){section=v;} public AcademicClass getAcademicClass(){return academicClass;} public void setAcademicClass(AcademicClass v){academicClass=v;} public String getAcademicYear(){return academicYear;} public void setAcademicYear(String v){academicYear=v;} public String getRollNumber(){return rollNumber;} public void setRollNumber(String v){rollNumber=v;} public AcademicStatus getStatus(){return status;} public void setStatus(AcademicStatus v){status=v;} public LocalDateTime getEnrolledAt(){return enrolledAt;} }
